/* Index-visible Purana dossier layer.
 * This is deliberately the final Purana data layer loaded by the Scripture Index.
 * It replaces generic completion prose with text-specific dating, structure,
 * contents and interpretation for the twenty Purana routes actually exposed there.
 */
(() => {
  const D=window.SCRIPTURE_DETAIL_DATA=window.SCRIPTURE_DETAIL_DATA||{};
  const ROCHER={title:'Ludo Rocher, The Puranas (1986)',url:'https://books.google.com/books?id=n0-4RJh5FgoC',detail:'Standard survey of Puranic textual history, recensions and bibliography.'};
  const HAZRA={title:'R. C. Hazra, Studies in the Puranic Records on Hindu Rites and Customs',url:'https://books.google.com/books?id=Jar4V3piCeQC',detail:'Foundational study of Puranic strata, quotation history, rites and chronology.'};
  const W=name=>({title:`${name} — public structure cross-check`,url:`https://en.wikipedia.org/wiki/${encodeURIComponent(name.replace(/ Purāṇa$/,' Purana').replace(/ /g,'_'))}`,detail:'Used only to cross-check familiar public structure and naming; historical claims follow specialist scholarship and editions.'});
  const S=(title,...paragraphs)=>({title,paragraphs});
  const C=(title,paragraphs,subsections=[])=>({title,paragraphs:Array.isArray(paragraphs)?paragraphs:[paragraphs],subsections});
  const clean=x=>typeof x==='string'?x
    .replace(/\b(?:a good|a serious|a full|a responsible|a historically careful|a text-focused) article (?:should|must|needs to)\b[^.]*\.?/gi,'')
    .replace(/\bthere is no need to\b[^.]*\.?/gi,'')
    .replace(/\bthis article (?:should|must|keeps|uses|treats)\b[^.]*\.?/gi,'')
    .replace(/\bthe value of a detailed article is to\b/gi,'')
    .replace(/\s{2,}/g,' ').trim():x;
  const scrub=o=>{if(Array.isArray(o))return o.map(scrub);if(o&&typeof o==='object'){Object.keys(o).forEach(k=>o[k]=scrub(o[k]));return o;}return clean(o);};

  const P={
    'Brahma Purāṇa':{
      period:'Extant compilation no earlier than about the 10th century CE in Hazra’s analysis, with major pilgrimage sections continuing to grow in the later medieval period.',
      structure:'245 chapters in the common surviving text, divided into Purvabhaga and Uttarabhaga; the extant work is dominated by regional mahatmya material.',
      rec:['Purvabhaga and Uttarabhaga in the received printed text.','Gautami/Godavari Mahatmya also circulated separately; Brahmottara material has a partly independent transmission.'],
      date:[`The present Brahma Purana is unlikely to be identical with the older work quoted under that title by medieval digest writers. Hazra noted that many verses attributed to a Brahma Purana in nibandhas are absent from the extant text and argued that the surviving compilation cannot be earlier than about the tenth century.`,`Its large sacred-geography blocks are later still in places. The surviving text devotes most of its space to the Godavari region and Odisha, including major temple and tirtha traditions; such material belongs to the history of regional pilgrimage institutions rather than to one primordial Purana composed at a single date.`],
      contents:[S('Purvabhaga — cosmology, genealogy and sacred geography','The opening preserves conventional Puranic cosmology, creation, genealogies and myth, but these topics occupy a relatively small share of the surviving work. They function as a universal frame for a text whose strongest extant identity is geographic.'),S('Gautami Mahatmya — the Godavari as a sacred system','A very large block maps myths, bathing places, gifts and ritual benefits onto the Godavari basin. The river is not merely listed as a tirtha: local places are integrated into a Puranic sacred history and the mahatmya could circulate independently.'),S('Odisha and temple geography','The text gives exceptional attention to sacred sites in Odisha, including Jagannatha/Puri and solar traditions associated with Konark. These chapters are among the clearest evidence that the received Brahma Purana grew through regional temple and pilgrimage culture.'),S('Philosophy and ritual compendia','Shorter sections include samskara, dharma, Samkhya and Yoga material. Their juxtaposition with mahatmyas shows how the title “Purana” became a container for geography, ritual and learned doctrine as well as mythic history.')],
      theology:[`The extant work is not well described as a “Brahma theology.” Vishnu, Shiva, Devi and Surya all receive substantial attention, while Jagannatha and regional sacred geography shape much of its devotional profile.`,`Its importance lies less in a single systematic doctrine than in showing how universal Puranic authority was attached to rivers, temples and regional cults.`],
      reception:[`The Gautami Mahatmya and Odisha sections acquired lives beyond the complete Purana. Their independent circulation is evidence that readers often encountered the Brahma Purana through regional ritual blocks rather than as a continuously read 245-chapter book.`],
      sources:[W('Brahma Purāṇa')]
    },
    'Padma Purāṇa':{
      period:'A highly composite Purana whose major khandas belong to different periods; much of the received pilgrimage and devotional material is medieval.',
      structure:'Two substantially different major recensions: a Bengal five-khanda form and a western/southern six-khanda form, with significant differences in order and extent.',
      rec:['Bengal recension: Srishti, Bhumi, Svarga, Patala and Uttara khandas.','Western/southern recension: six khandas, commonly Adi/Svarga, Bhumi, Brahma, Patala, Srishti and Uttara; chapter contents and ordering differ substantially.'],
      date:[`No single date meaningfully describes the Padma Purana. Its great khandas are compilations with different regional and sectarian histories, and the Bengal and western/southern recensions differ too substantially to be treated as minor copies of one fixed archetype.`,`Pilgrimage guides, festival observances, Rama and Krishna materials, theological passages and later mahatmyas entered the corpus at different times. Dating therefore works best section by section, using quotations, parallel texts, sectarian vocabulary and regional manuscript evidence.`],
      contents:[S('Srishti/Adi materials — creation and sacred beginnings','Creation, cosmology, genealogical material and narratives of gods establish the universal frame, but their exact location changes with recension.'),S('Bhumi and Svarga — pilgrimage as the dominant geography','Large stretches turn rivers, forests and tirthas into a ritual map. Stories are woven into travel instructions so that sacred geography, merit and narrative mutually authorize one another.'),S('Patala — Rama, Krishna and sectarian narrative','The Patala material includes a distinctive Rama cycle and substantial Vaishnava narrative, while other chapters glorify Shiva. It cannot be reduced to one sectarian program.'),S('Uttara — festivals, mahatmyas and liberation teachings','The huge Uttara block includes vrata and festival material, Gita- and Bhagavata-mahatmya traditions, Shiva-oriented teaching and discussions of liberation. It is a major witness to the open-ended growth of medieval Puranic compendia.')],
      theology:[`The Padma Purana contains strong Vaishnava, Shaiva and tirtha-centered strata. Later sectarian classifications of Puranas do not adequately describe the internal plurality of the surviving recensions.`,`Its most characteristic religious mechanism is often mahatmya: places, texts, months, vows and acts of recitation become sacred by being inserted into divine narrative and assigned specific fruits.`],
      reception:[`Because individual khandas and mahatmyas circulated separately, “Padma Purana” in later quotation can refer to a local textual block rather than to the same six-part printed edition used today. Recension must therefore be named when precise wording or chapter number matters.`],
      sources:[W('Padma Purāṇa')]
    },
    'Viṣṇu Purāṇa':{
      period:'One of the older and more tightly organized Mahapuranas; core formation is commonly placed in the mid-first millennium CE, with later revisions.',
      structure:'6 amshas/books and 126 chapters in the received text; roughly 7,000 surviving verses against the traditional total of 23,000.',
      rec:['Six-amsha architecture is unusually stable at the large scale.','A modern critical edition was prepared under M. M. Pathak at the Oriental Institute, Vadodara.'],
      date:[`The Vishnu Purana is generally placed among the earlier surviving Mahapuranas. Its comparatively coherent six-book architecture, substantial concentration on the classical Puranic topics of creation, manvantaras and dynasties, and its relation to Vayu/Brahmanda-type genealogical material point to a core in the middle centuries of the first millennium CE, although the text continued to be revised.`,`Its dating should not be derived from the age of individual myths. The Krishna narrative, dynastic lists and cosmological schemes draw on older traditions, while their arrangement into the received six-amsha work reflects a later Puranic redaction.`],
      contents:[S('Book 1 — creation and the Vishnu-centered cosmos','Creation, Prakriti, cosmic beings, Dhruva and Prahlada establish Vishnu as the sustaining ground through stories that connect cosmology to devotion.'),S('Book 2 — worlds, geography and cosmic time','Jambudvipa, planetary and cosmic geography, Bharata and cycles of time situate human history within a vast recurring universe.'),S('Books 3–4 — manvantaras and dynasties','Vedic branches, duties and manvantaras lead into solar and lunar genealogies. These books are central to the text’s reputation as one of the Puranas closest to the pancalakshana ideal.'),S('Book 5 — Krishna','The Krishna cycle reworks material known from epic and Harivamsha traditions into a sustained Vaishnava sacred history.'),S('Book 6 — Kali age and liberation','The final book turns from decline in the Kali age to dissolution and the relation of knowledge, devotion and liberation.')],
      theology:[`Vishnu is both cosmic ground and personal Lord, but the work preserves older cosmological and genealogical structures rather than becoming only a devotional biography.`,`Its synthesis of avatara, cosmic cycles, dharma and liberation was exceptionally important for later Vaishnava theology and for the development of Puranic sacred history.`],
      reception:[`The Vishnu Purana supplied a major source for later Vaishnava narrative and theology and was repeatedly compared with the Harivamsha and Bhagavata. Its six-book coherence also made it especially attractive to early modern translators and modern historians of the Purana genre.`],
      critical:[`The Oriental Institute, Vadodara, published M. M. Pathak’s critical edition in two volumes. Its apparatus is particularly useful where popular editions silently normalize readings or chapter divisions.`],
      sources:[W('Viṣṇu Purāṇa'),{title:'Oriental Institute, MS University of Baroda — Vishnu Purana critical edition project',url:'https://msubaroda.ac.in/academics/FOA/Departments/OI/Programs/447'}]
    },
    'Vāyu Purāṇa':{
      period:'An old Puranic compilation with a substantial core probably in the 4th–5th centuries CE, followed by later additions including dharma and regional mahatmya material.',
      structure:'Two competing large-scale arrangements survive: four padas totaling 112 chapters in some editions, and a two-khanda arrangement in others.',
      rec:['Anandashrama/Vangavasi: Prakriya 1–6, Anushanga 7–64, Upodghata 65–99, Upasamhara 100–112.','Asiatic Society/Venkateshvara: Prathama and Dvitiya khandas; the Gaya Mahatmya is absent from some manuscripts.'],
      date:[`The Vayu Purana belongs to the older stratum of surviving Puranic literature. Its extensive overlap with the Brahmanda Purana points to a shared textual ancestry, and Hazra argued that their separation as distinct works had occurred by roughly the fifth century CE.`,`The received Vayu is nevertheless stratified. Dharma, ascetic and samskara chapters and the Gaya Mahatmya have uneven manuscript support and are later than the old cosmological-genealogical core. The absence of the Gaya block in some witnesses is direct evidence of accretion rather than an abstract claim that “Puranas are layered.”`],
      contents:[S('Prakriya — cosmogonic opening','The opening chapters establish creation and the conditions of cosmic order.'),S('Anushanga — cosmology, genealogy and sacred history','The long middle develops geography, astronomy, manvantaras, genealogies and dynastic memory. This is the old encyclopedic core most closely related to the Brahmanda Purana.'),S('Upodghata and later normative blocks','Later chapters incorporate dharma, rites of passage, ascetic discipline, music and other learned material, showing continued expansion of the text’s remit.'),S('Gaya Mahatmya','The final pilgrimage guide sacralizes Gaya through ancestral rites and tirtha mythology. Its absence from some manuscripts and independent citation history make it a particularly clear late textual block.')],
      theology:[`The Vayu is not primarily a sectarian “wind-god Purana.” Its importance is cosmological, genealogical and historical, though Shaiva/Pashupata and pilgrimage materials are also significant.`,`Its close relationship with Brahmanda makes it one of the most important witnesses for reconstructing the development of early Puranic cosmology and dynastic tradition.`],
      reception:[`The work was known to early medieval authors and later became a major source for historians mining Puranic genealogies. Those lists are textual constructions with variant transmission and cannot be converted mechanically into a modern chronological table.`],
      sources:[W('Vāyu Purāṇa')]
    },
    'Śiva Purāṇa':{
      period:'A composite Shaiva Purana whose surviving redactions are largely medieval; older material is present, but much of the extant corpus took shape from roughly the 10th century onward.',
      structure:'The surviving text exists in sharply different recensions, most notably six-samhita and seven-samhita arrangements with very different chapter totals.',
      rec:['A common seven-samhita recension has about 457 chapters.','Another major recension has six samhitas and about 290 chapters.','Manuscripts also preserve alternative two-khanda and other arrangements.'],
      date:[`The Shiva Purana cannot be dated from one chapter total because the manuscript tradition preserves substantially different works under the same title. Its extant redactions are medieval, with older Shaiva myths and ritual traditions embedded inside them and some sections continuing to grow well after the earliest recoverable core.`,`The traditional claim that a vastly larger twelve-samhita, 100,000-verse Shiva Purana was abridged belongs to the text’s own canonical memory; it is not equivalent to a surviving manuscript of that lost form. The six- and seven-samhita recensions are the concrete textual witnesses that modern study must compare.`],
      contents:[S('Vidyeshvara and the theology of the linga','Opening materials establish Shiva’s supremacy, the linga and practices of Shaiva worship.'),S('Rudra/Shatarudra traditions','Creation, manifestations of Rudra, forms of Shiva and ritual theology expand the Lord’s cosmic presence.'),S('Kotirudra and ritual practice','Linga installation, worship, vows and sacred places connect mythic Shaivism to temple and domestic practice.'),S('Uma, Kailasa and the divine household','Marriage, Parvati, Skanda, Ganesha and Kailasa narratives make the divine family a central theological and devotional world.'),S('Vayaviya material','Later teaching sections include cosmology, yoga, liberation and Shaiva doctrine, often through extended instructional dialogue.')],
      theology:[`The linga is not merely an aniconic object in this text: it is a theological sign through which Shiva’s transcendent and manifest forms are coordinated.`,`The Purana also makes the divine household—Shiva, Parvati, Ganesha and Skanda—central to cosmic and devotional order, helping explain its wide ritual and narrative reception.`],
      reception:[`Different printed Shiva Puranas may not contain the same samhitas or chapter numbering. Citation therefore requires naming the edition or recension rather than treating “Shiva Purana chapter X” as universally stable.`],
      sources:[W('Śiva Purāṇa')]
    },
    'Bhāgavata Purāṇa':{
      period:'Composite Vaishnava Purana of the later first millennium CE; Friedhelm Hardy influentially placed its major redaction in the 9th or early 10th century, while earlier strata and alternative datings remain debated.',
      structure:'12 skandhas; common editions often count 335 chapters, while the Ahmedabad critical edition constitutes 329 chapters, 13,129 metrical stanzas and 452 prose passages.',
      rec:['Large pan-Indian manuscript tradition in numerous scripts.','Ahmedabad critical edition (1996–2002) distinguishes constituted text from many short and long interpolations.'],
      date:[`The Bhagavata’s final redaction belongs to a mature phase of Sanskrit Krishna devotion. Hardy connected its emotional Krishna bhakti, especially separation-love, with South Indian devotional traditions and proposed a ninth- or early-tenth-century redaction; the work was certainly known by the early eleventh century.`,`Its twelve-skandha architecture contains older mythic and philosophical materials, so the date of the redaction is not the date of every story. Comparison with the Harivamsha, Vishnu Purana, earlier Krishna traditions and Tamil devotional literature is central to the chronological problem.`],
      contents:[S('Skandhas 1–2 — death frame and the question of the highest good','Parikshit’s seven-day approach to death and the Suta/Naimisha frame make hearing sacred narrative itself the setting for theology.'),S('Skandhas 3–5 — creation, Kapila, Dhruva, Prithu, Rishabha and Bharata','Cosmology and exemplary lives progressively test how devotion, knowledge and kingship relate to liberation.'),S('Skandhas 6–9 — Ajamila, Prahlada, Gajendra, Vamana and dynasties','Stories repeatedly place salvific devotion in unexpected agents and situations while preserving manvantara and royal genealogy.'),S('Skandha 10 — Krishna','The largest book turns Krishna’s Vraja, Mathura and Dvaraka lives into a theology of lila and increasingly intense modes of bhakti.'),S('Skandhas 11–12 — Uddhava, Yadava end and Kali','The Uddhava teaching synthesizes bhakti, yoga, renunciation and knowledge before the destruction of the Yadavas and the work’s eschatological close.')],
      theology:[`The Bhagavata distinguishes Brahman, Paramatman and Bhagavan while placing Bhagavan—and devotion to Krishna—at the center of its religious hierarchy. Bhakti is repeatedly valued not merely as a technique for another reward but as the desired relation to the divine itself.`,`Its theology is deliberately capacious: Samkhya, Yoga, Vedantic language, avatara cosmology and ecstatic devotion are integrated into one narrative scripture rather than reduced to a single later school.`],
      reception:[`Shridhara Svamin’s Bhavarthadipika became a major Sanskrit commentary, and the text later became foundational for Vallabha, Gaudiya, Madhva and other Vaishnava traditions. Skandha 10 dominates art and popular retelling, but the wider Purana is essential for understanding why Krishna lila is presented as the culmination of a complete cosmology.`],
      critical:[`The B. J. Institute of Learning and Research, Ahmedabad, published a multi-volume critical edition between 1996 and 2002 under H. G. Shastri, Bharati K. Shelat and K. K. Shastree. Its 329-chapter constituted text demonstrates why the traditional “18,000 verses” and popular chapter counts should not be treated as literal manuscript constants.`],
      sources:[W('Bhāgavata Purāṇa'),{title:'Friedhelm Hardy, Viraha-Bhakti',url:'https://books.google.com/books?id=XY42EAAAQBAJ',detail:'Influential study of South Indian Krishna devotion and Bhagavata chronology.'}]
    },
    'Devī Bhāgavata Purāṇa':{
      period:'Medieval Shakta Purana, commonly placed roughly between the 10th and 12th centuries in substantially received form, though proposed ranges are broader.',
      structure:'12 skandhas and 318 chapters; traditional extent 18,000 verses.',
      rec:['Twelve-skandha architecture is the normal received form.','Its status as Mahapurana versus Upapurana varies by sectarian canon and should be reported as a reception question, not solved by fiat.'],
      date:[`The Devi Bhagavata belongs to the medieval consolidation of Goddess-centered Puranic theology. Hazra and later scholars place its substantially received form around the eleventh–twelfth centuries, while broader estimates extend on either side. Its sophisticated identification of Devi with Brahman and its engagement with bhakti, Samkhya and Vedanta belong to this mature Shakta intellectual environment.`,`The text is not simply a feminine rewriting of the Bhagavata Purana. Shared twelve-skandha scale and Puranic conventions coexist with a distinct Goddess-centered cosmology, ritual world and canon of narratives.`],
      contents:[S('Skandhas 1–3 — frame, creation and the Goddess as cosmic source','The opening establishes the narrative frames and re-centers creation around Mahadevi as the power underlying gods and cosmos.'),S('Skandhas 4–6 — dynasties, incarnational narratives and sacred history','Epic and Puranic stories are retold through a Shakta hierarchy in which divine powers depend on the Goddess.'),S('Skandha 7 — Devi Gita','The book culminates in an extended theological teaching in which the Goddess expounds her cosmic nature, devotion, knowledge and liberation.'),S('Skandhas 8–12 — cosmology, worship and Manidvipa','Later books combine cosmography, ritual, mantra, observance and descriptions of the supreme Goddess’s realm, giving the Purana a strongly liturgical as well as narrative close.')],
      theology:[`Mahadevi is not one deity among peers: she is identified with the ultimate reality from which Brahma, Vishnu and Shiva derive their capacities. This is the text’s defining theological reversal of more familiar male-centered Puranic hierarchies.`,`The Devi Gita coordinates devotion to a personal Goddess with nondual and yogic language, making the Purana a major source for later Shakta Vedantic synthesis.`],
      reception:[`Shakta traditions frequently treat the work as a Mahapurana, while other canonical lists classify it differently. That disagreement is historically meaningful because “Mahapurana” status itself became a field of sectarian canon-making.`],
      sources:[W('Devī Bhāgavata Purāṇa')]
    },
    'Nāradīya Purāṇa':{
      period:'Composite Vaishnava Purana with an older core before the 11th century and substantial later material; not to be confused with the Brihannaradiya Upapurana.',
      structure:'Purvabhaga in 4 padas, 125 chapters; Uttarabhaga, 82 chapters; 207 chapters in the common arrangement.',
      rec:['Naradiya/Narada Mahapurana: two bhagas, 207 chapters.','Brihannaradiya Purana: a different Upapurana of 38 chapters; older scholarship often confused the two.'],
      date:[`The first task in dating the Naradiya is identifying the correct text. Nineteenth-century scholarship often confused the Naradiya Mahapurana with the shorter Brihannaradiya Upapurana. Manuscript study distinguishes them as separate works.`,`Hazra placed substantial portions of the Purvabhaga and Uttarabhaga before the eleventh century while regarding other material as later. The received 207-chapter work is therefore a layered Vaishnava compendium rather than a single late authorial composition.`],
      contents:[S('Purvabhaga — encyclopedic Vaishnava instruction','Four padas combine devotion, ritual, pilgrimage, cosmology and summaries of other sacred knowledge. The breadth is characteristic of a medieval compendium rather than a continuous mythic narrative.'),S('Purana summaries and bibliographic memory','The work is unusually important for describing or summarizing other Puranas. These notices preserve a medieval map of the genre and are often used to compare what a Purana was expected to contain with what survives today.'),S('Uttarabhaga — Rukmangada and vrata','The later half centers on the Rukmangada narrative and the religious force of observance, especially Vaishnava vows and calendrical practice.')],
      theology:[`Narada is an ideal transmitter for a text concerned with devotion, recitation and the circulation of sacred knowledge. Vaishnava bhakti provides the dominant orientation, but the work’s encyclopedic form remains as important as sectarian praise.`],
      reception:[`The Naradiya’s summaries of other Puranas make it a crucial witness for textual history: when its description of another Purana does not match the surviving work, the mismatch can reveal loss, growth or recensional change.`],
      sources:[W('Naradiya Purāṇa')]
    },
    'Mārkaṇḍeya Purāṇa':{
      period:'One of the older Mahapuranas, with a core usually placed in the early-to-mid first millennium CE; the Devi Mahatmya is commonly dated around the 5th–6th centuries.',
      structure:'137 chapters in the common received text; chapters 81–93 form the Devi Mahatmya in the widely used numbering.',
      rec:['A relatively compact narrative Purana rather than a huge tirtha compendium.','Modern critical edition prepared under M. L. Wadekar at the Oriental Institute, Vadodara.'],
      date:[`The Markandeya Purana is relatively early within the extant Mahapurana corpus. Its narrative frame links Jaimini’s unanswered Mahabharata questions to the teachings of wise birds, and much of its material precedes the large medieval mahatmya expansions characteristic of several other Puranas.`,`The Devi Mahatmya is a distinct and enormously influential block embedded in the Purana. It is commonly placed around the fifth–sixth centuries CE; dating that unit separately avoids making the age of the Goddess scripture automatically identical with every surrounding chapter.`],
      contents:[S('Jaimini and the birds — questions left by the Mahabharata','Jaimini is redirected from Markandeya to four wise birds, whose answers generate a long sequence of ethical, karmic and mythological teaching. The frame makes the Purana explicitly continue problems posed by epic literature.'),S('Dattatreya, yoga and moral narratives','Early-middle chapters include instruction on karma, liberation and yoga together with exemplary stories. Dattatreya’s teaching gives the work a distinctive philosophical profile.'),S('Devi Mahatmya, chapters 81–93','The battles against Madhu-Kaitabha, Mahishasura and Shumbha-Nishumbha present the Goddess as the concentrated power of the gods and as supreme cosmic agency. This embedded work became independently recited as Durga Saptashati/Chandi.'),S('Later dynastic and manvantara material','The Purana returns from Goddess epic to manvantaras and royal history, reinforcing that the Devi Mahatmya is a major embedded composition rather than the whole book.')],
      theology:[`The Markandeya is not uniformly Shakta, but the Devi Mahatmya transformed the history of Goddess theology by presenting Devi as both immanent divine power and supreme transcendent reality.`,`The surrounding Purana’s yoga, karma and dharma discussions give a broader frame in which liberation is not confined to one sectarian vocabulary.`],
      reception:[`The Devi Mahatmya acquired an independent ritual life far greater than the complete Markandeya Purana. Its recitation in Navaratri and Shakta worship is therefore reception of a specific embedded text, not evidence that all 137 chapters share one liturgical function.`],
      critical:[`The Oriental Institute, Vadodara, has published a critical edition of the Markandeya Purana under M. L. Wadekar, providing a modern philological basis beyond the older printed vulgate.`],
      sources:[W('Mārkaṇḍeya Purāṇa')]
    },
    'Agni Purāṇa':{
      period:'A layered medieval encyclopedia whose core was in circulation by about the 10th–11th centuries, with additions continuing for centuries.',
      structure:'About 382–383 chapters in common editions and roughly 12,000–15,000 surviving verses; highly heterogeneous rather than organized as one sustained narrative.',
      rec:['Chapter counts around 382–383 in common printed traditions.','Technical blocks often have close parallels in specialist shastra literature and may have circulated independently.'],
      date:[`The Agni Purana is best dated as an accumulating encyclopedia, not as a single mythic composition. It was known in the early medieval period, but its technical and ritual materials show continuing growth, with some strata considerably later than the earliest core.`,`Its subject matter is itself chronological evidence: poetics, dramaturgy, architecture, iconography, medicine, grammar, polity, warfare and ritual have distinct source histories. Dating one borrowed or adapted technical block does not date the whole Purana.`],
      contents:[S('Myth and avatara summaries','Short mythological and epic summaries provide a Puranic sacred frame, but they occupy far less of the text than the title “Purana” might suggest.'),S('Temple, image and ritual sciences','Architecture, iconography, consecration and worship turn the book into a handbook for material religious culture.'),S('Polity, warfare and practical knowledge','Kingship, weapons, fortification and related subjects connect sacred authority to the techniques of rule.'),S('Poetics, drama, grammar and lexicography','The later chapters preserve condensed literary theory and linguistic material, making the Agni one of the most encyclopedic Sanskrit Puranas.'),S('Medicine, omens and other sciences','Medical and prognostic passages further demonstrate that the work functions as a portable digest of learned disciplines.')],
      theology:[`The dialogue of Agni and Vasishtha gives scriptural authority to an extraordinary range of technical knowledge. Its religious significance lies partly in this act of encyclopedic inclusion rather than in a single sectarian theology.`],
      reception:[`Modern readers often mine individual Agni chapters for architecture, iconography or poetics. Such use is legitimate only when the local chapter, its parallels and manuscript history are distinguished from the date and doctrine of the Purana as a whole.`],
      sources:[W('Agni Purāṇa')]
    },
    'Bhaviṣya Purāṇa':{
      period:'An exceptionally unstable living compilation whose extant manuscripts contain material from the medieval period through the early modern and modern eras.',
      structure:'No single stable structure: manuscripts may have four parvans, two parts or other arrangements; at least five major versions are known.',
      rec:['Common labels include Brahma, Madhyama, Pratisarga and Uttara/Bhavishyottara parvans.','Versions differ radically in contents and extent; chapter numbers cannot be transferred safely between editions.'],
      date:[`The Bhavishya Purana is the clearest case on the index where a single composition date would be misleading. Its manuscripts differ drastically, and the surviving corpus includes texts that continued to absorb material about changing ritual calendars, religious communities and political history into the nineteenth century.`,`The name “Bhavishya,” future, encouraged retrospective prophecy: events already known to a redactor could be narrated as predictions. References to Islam, Christianity, Sikhism, Mughal and British rule therefore belong to demonstrably late strata and cannot be used as evidence that an ancient manuscript predicted those events.`],
      contents:[S('Brahma Parvan — dharma and solar material','The opening includes normative and ritual material, some of it parallel to older dharma and Saura traditions.'),S('Madhyama Parvan — ritual and tantric material','This block differs markedly in genre from conventional dynastic Purana and reflects specialized medieval ritual interests.'),S('Pratisarga Parvan — repeated creation and historical “prophecy”','The notorious historical sections name later religions, rulers and events. Their language and content make them crucial evidence for ongoing redaction, not supernatural dating evidence.'),S('Uttara/Bhavishyottara — vrata, festival and calendar','The final corpus is rich in observances, gifts and festival instructions and also circulated under the title Bhavishyottara Purana.')],
      theology:[`The Bhavishya is less coherent as a theology than as a record of Puranic adaptability. Its changing strata show how scriptural authority could continually absorb new ritual practices and new historical worlds.`],
      reception:[`Claims based on the Pratisarga sections require exact manuscript and edition identification. “The Bhavishya Purana says…” is especially unreliable when the cited passage belongs only to a late or regional recension.`],
      sources:[W('Bhaviṣya Purāṇa')]
    },
    'Brahmavaivarta Purāṇa':{
      period:'The extant Krishna-Radha-centered recension is largely a late medieval work, probably shaped in Bengal around the 15th–16th centuries, though an older Purana under the same title existed.',
      structure:'4 khandas: Brahma (30 chapters), Prakriti (67), Ganesha (46), Krishna (about 131–133); total about 274–276 chapters depending on recension.',
      rec:['Brahma, Prakriti, Ganesha/Ganapati and Krishna khandas.','Numerous manuscripts differ in chapter totals; the extant work is not identical with the older Brahmavaivarta cited in earlier literature.'],
      date:[`An older Brahmavaivarta Purana was known before the present text, but the surviving work’s intense Radha-Krishna theology and Bengali devotional setting point to a major reconstitution in the fifteenth–sixteenth centuries. Earlier quotations should therefore not automatically be assigned to the chapters now printed under the same title.`,`The Krishna Khanda is especially important chronologically because its Goloka and Radha-centered theology belongs to the mature medieval development of Krishna devotion.`],
      contents:[S('Brahma Khanda','Creation and the nature of Brahman are recast within a Krishna-centered hierarchy.'),S('Prakriti Khanda','The Goddess and multiple female divine powers are systematized as forms of primordial Prakriti.'),S('Ganesha Khanda','Ganesha’s birth, myths and worship receive a full independent book within the Vaishnava frame.'),S('Krishna Khanda','The largest section presents Radha and Krishna in Goloka and develops an intimate devotional cosmology in which Krishna is the supreme source even of Vishnu and other gods.')],
      theology:[`The Purana’s defining move is to make Krishna, together with Radha, the summit of reality and to place Goloka above more familiar Vaishnava heavens. Radha is not merely a heroine of Krishna narrative but a cosmic principle inseparable from him.`,`The four-khanda arrangement also absorbs Devi and Ganesha traditions into this Krishna-centered universe, illustrating a late Puranic strategy of theological inclusion through hierarchy.`],
      reception:[`The work is important for the history of Radha theology and Bengali Krishna devotion, but it never displaced the Bhagavata as the most widely authoritative Sanskrit Krishna Purana. Its late redaction is part of its historical significance, not a defect.`],
      sources:[W('Brahma Vaivarta Purāṇa')]
    },
    'Varāha Purāṇa':{
      period:'Composite medieval Purana, with substantial surviving material commonly placed around the 10th–12th centuries and different sections showing distinct histories.',
      structure:'Critical edition: 215 chapters; printed editions often 217–218. The Naradiya describes a Purvabhaga and a lost Uttarabhaga not preserved in extant Varaha manuscripts.',
      rec:['Extant Purvabhaga corresponds broadly to the portion summarized by the Naradiya Purana.','The Uttarabhaga described by the Naradiya is lost from surviving Varaha manuscripts.','Hazra distinguished four internal blocks by changing interlocutors.'],
      date:[`The Varaha Purana is unusually transparent about compositional plurality. Hazra divided the extant text into four blocks whose interlocutors and literary character change, indicating successive redaction rather than one authorial plan.`,`The loss of the Uttarabhaga known to the Naradiya Purana provides external evidence that the work once had a different extent. The surviving 215-chapter critical text is therefore only one historical state of the Varaha tradition.`],
      contents:[S('Chapters 1–112 — Varaha and Prithvi','The opening dialogue combines Vaishnava cosmology, sacred geography, myth and worship under the authority of the boar avatara.'),S('Chapters 113–192 — transmitted dialogue and tirtha material','The framing shifts as Suta recounts Prithvi’s teaching to Sanatkumara; pilgrimage and regional sacred geography become increasingly prominent.'),S('Chapters 193–212 — Dharma Samhita','Janamejaya and Vaishampayana frame a normative block concerned with dharma, giving the Purana an epic-scholastic register distinct from the opening.'),S('Final chapters — Brahma and Sanatkumara','A final change of speakers further demonstrates that the received book is a stitched corpus rather than one continuous dialogue.')],
      theology:[`Although named for Vishnu’s Varaha avatara, the Purana’s strongest surviving identity is a combination of Vaishnava myth, pilgrimage and dharma rather than an extended retelling of the boar myth itself.`],
      reception:[`The missing Uttarabhaga and changing dialogue frames make the Varaha an important example of why Puranic “contents lists” in one text can preserve evidence for lost forms of another.`],
      critical:[`Anand Swarup Gupta’s All-India Kashiraj Trust critical edition constitutes 215 chapters and provides the most useful modern baseline for discussing the surviving text.`],
      sources:[W('Varāha Purāṇa')]
    },
    'Liṅga Purāṇa':{
      period:'Composite Shaiva Purana with an older core variously placed between the 5th and 10th centuries CE and substantial later expansion.',
      structure:'Two parts: Purvabhaga, 108 chapters; Uttarabhaga, 55 chapters in surviving versions, although the text itself once describes the latter as 46 chapters.',
      rec:['Purvabhaga/Purvardha: 108 chapters.','Uttarabhaga/Uttarardha: 55 extant chapters; an internal statement of 46 suggests later expansion.'],
      date:[`The mismatch between the extant 55 chapters of the Uttarabhaga and the text’s own statement that it contained 46 is unusually concrete evidence of growth. The Linga Purana should therefore be dated as a layered Shaiva corpus, with older cosmological and linga theology supplemented by later ritual and pilgrimage blocks.`,`Proposed dates for its oldest core range widely from the fifth to tenth centuries. That uncertainty is better preserved than replaced by a single false precision, because different portions engage different stages of Shaiva ritual and theology.`],
      contents:[S('Purvabhaga — linga, creation and Shiva’s cosmic forms','The linga is presented as a sign of the unmanifest and as the axis through which creation and divine manifestation can be understood.'),S('Mythic and ritual Shaivism','Narratives of Shiva, sacred places, vows and modes of worship connect cosmic linga theology to repeated religious practice.'),S('Uttarabhaga — expanded ritual and doctrinal material','The later part develops worship, cosmology and liberation teaching; its chapter-count discrepancy points to textual growth after an earlier internal table of contents.')],
      theology:[`The work’s central problem is how the formless, immeasurable Shiva can be present in a worshipped linga. Its mythology repeatedly mediates between transcendent principle, anthropomorphic deity and material cult image.`,`Vishnu and Brahma are not absent; their relation to Shiva is part of the linga’s claim to encompass creation, preservation and dissolution.`],
      reception:[`The Linga Purana became a major scriptural resource for Shaiva worship and linga theology, but its two-part transmission must be kept in view when passages are quoted as though the text had always possessed its present extent.`],
      sources:[W('Liṅga Purāṇa')]
    },
    'Skanda Purāṇa':{
      period:'A vast Shaiva pilgrimage corpus with an early Skandapurana stratum attested by an early-9th-century Nepalese manuscript, alongside much later khanda and mahatmya traditions.',
      structure:'No single universal architecture: an early Skandapurana recension differs profoundly from later six-samhita and seven-khanda printed corpora.',
      rec:['Early Skandapurana: represented by Nepalese manuscripts and reconstructed by the Groningen Skandapurana Project.','Later printed traditions organize enormous material into six samhitas or seven major khandas, with regional mahatmyas and recensional differences.'],
      date:[`The Skanda Purana is not one chronologically uniform “largest Purana.” An early recension is preserved in Nepalese palm-leaf manuscripts, including a witness dated to the early ninth century, and critical work reconstructs a text substantially different from many huge modern printed Skanda corpora.`,`Later Kashi, Reva, Prabhasa and other regional blocks grew around pilgrimage networks over centuries. The title Skanda Purana thus names both an early Shaiva Puranic composition and a vast accreting library of tirtha mahatmyas.`],
      contents:[S('Early Skandapurana — Shaiva myth and sacred geography','The early recension centers Shiva, his manifestations, sacred places and the formation of Shaiva religious geography rather than functioning primarily as a biography of Skanda.'),S('Kashi traditions','Large later blocks map Varanasi as a salvific sacred city, integrating temple topography, myth and ritual action.'),S('Reva/Narmada traditions','Narmada pilgrimage literature turns the river into an extended ritual landscape; attribution and recension must be checked because Reva materials have shifted between Vayu and Skanda printed traditions.'),S('Prabhasa and other regional mahatmyas','Western Indian and other regional pilgrimage corpora demonstrate how the Skanda title became a vehicle for local sacred geographies.')],
      theology:[`The early work is fundamentally Shaiva: Skanda is important, but Shiva and the sanctification of places dominate much of its religious world. The later mahatmyas make presence in sacred geography as important as mythic narrative.`,`Its growth shows how a Purana could function as an expandable archive through which local temples, rivers and pilgrimage circuits entered pan-Indian Sanskrit sacred history.`],
      reception:[`Modern printed Skanda Puranas may combine materials absent from the early Nepalese recension. Scholars therefore distinguish the critically edited early Skandapurana from later khanda traditions rather than treating every passage under the title as one manuscript lineage.`],
      critical:[`The Groningen Skandapurana Project has produced a multi-volume critical edition of the early text from Nepalese and related witnesses. It is one of the most important modern examples of rigorous Puranic textual criticism.`],
      sources:[W('Skanda Purāṇa'),{title:'Groningen Skandapurana Project',url:'https://www.rug.nl/research/centre-for-religious-studies/research-centres/skandapurana-project/',detail:'Critical-edition project for the early Skandapurana tradition.'}]
    },
    'Vāmana Purāṇa':{
      period:'Medieval Purana whose surviving core is most often placed around the 9th–11th centuries CE.',
      structure:'Critical edition: 69 chapters plus a 28-chapter Saro Mahatmya; earlier printed editions commonly had about 95–96 chapters. A four-samhita Brihad-Vamana described in tradition is lost.',
      rec:['All-India Kashiraj Trust critical text: 69 chapters + 28-chapter Saro Mahatmya.','Older printed arrangement: about 95–96 chapters.','The four-samhita Brihad-Vamana mentioned by the tradition does not survive.'],
      date:[`The Vamana Purana’s title can mislead: the surviving work is not primarily an extended Vaishnava account of Vishnu’s dwarf avatara. Its medieval core contains extensive Shaiva and pilgrimage material, and most scholarly datings cluster around the ninth–eleventh centuries.`,`The lost Brihad-Vamana remembered as four samhitas and the sharp reduction from old printed chapter counts to the 69-chapter critical text show that the history of the title is larger than the surviving recension.`],
      contents:[S('Vamana frame and mixed mythology','The opening asks about Vishnu’s Vamana avatara, but the narrative quickly broadens into a mixed Puranic corpus.'),S('Shaiva narratives','A large share of the surviving text glorifies Shiva and associated myths, making simple sectarian classification inadequate.'),S('Saro Mahatmya','The 28-chapter supplement maps sacred sites around Kurukshetra/Thanesar and neighboring regions, giving the work a strong north-Indian pilgrimage identity.')],
      theology:[`The Vamana is an excellent warning against classifying Puranas by title alone. A Vishnu avatara supplies the name, but Shaiva mythology and regional tirtha religion occupy much of the surviving text.`],
      reception:[`The critical edition’s separation of the Saro Mahatmya and its shorter constituted text make edition identification essential when chapter numbers are cited.`],
      critical:[`Anand Swarup Gupta’s All-India Kashiraj Trust critical edition constitutes 69 chapters and prints the 28-chapter Saro Mahatmya separately, replacing the older assumption that the 95–96 chapter vulgate represented one stable text.`],
      sources:[W('Vāmana Purāṇa')]
    },
    'Kūrma Purāṇa':{
      period:'Medieval synthetic Purana with a core often placed around the 8th century and later revisions extending into subsequent centuries.',
      structure:'Critical edition: 95 chapters, divided into Purva-vibhaga (51) and Upari-vibhaga (44); about 6,000 surviving verses against a traditional 17,000.',
      rec:['Purva-vibhaga: 51 chapters in the critical edition.','Upari-vibhaga: 44 chapters in the critical edition.'],
      date:[`The Kurma Purana belongs to the medieval phase in which Vaishnava, Shaiva and Shakta traditions were increasingly articulated in relation to one another. Its early core is often placed around the beginning of the eighth century, while legal, ritual and pilgrimage materials continued to be revised.`,`Its theological inclusiveness is not generic “Hindu tolerance” but a textual strategy visible in specific sections: a Vishnu avatara frames a work that gives Shiva a major teaching role and treats multiple divine powers with high theological status.`],
      contents:[S('Kurma-Narayana frame','Vishnu’s tortoise form functions as teacher and gives formal unity to a text whose contents extend far beyond the ocean-churning myth.'),S('Ishvara Gita','Shiva expounds metaphysics, yoga and liberation inside a nominally Vaishnava Purana, one of the work’s most distinctive signs of theological synthesis.'),S('Vyasa Gita and dharma','Normative teaching on social and life-stage duties sits beside liberation discourse, showing the Purana’s effort to coordinate household order and higher knowledge.'),S('Kashi and pilgrimage','Sacred geography, especially Shaiva Varanasi, joins doctrinal synthesis to actual pilgrimage institutions.')],
      theology:[`The Kurma is one of the least useful texts for a rigid “Vaishnava versus Shaiva” classification. Its importance lies precisely in the way Vishnu, Shiva and Shakti are coordinated within a shared cosmological and soteriological hierarchy.`,`Yoga provides a bridge between sectarian devotion and contemplative liberation: techniques of discipline are retained but their goal is interpreted through divine knowledge.`],
      reception:[`The Ishvara Gita and dharma blocks were cited independently by later authors, giving parts of the Kurma an afterlife distinct from the complete Purana.`],
      critical:[`Anand Swarup Gupta’s critical edition for the All-India Kashiraj Trust constitutes 95 chapters, 51 in the Purva-vibhaga and 44 in the Upari-vibhaga.`],
      sources:[W('Kūrma Purāṇa')]
    },
    'Matsya Purāṇa':{
      period:'An old and repeatedly revised Purana, with substantial early-first-millennium material and later technical, ritual and pilgrimage additions.',
      structure:'Common editions have about 291 chapters and 13,000–15,000 extant verses; other manuscript traditions differ sharply, including a much shorter Tamil Grantha recension.',
      rec:['Common north-Indian printed tradition: about 291 chapters.','Tamil Grantha manuscript tradition preserves a much shorter two-part form, demonstrating major recensional variation.'],
      date:[`The Matsya Purana preserves some of the older surviving Puranic cosmological and dynastic material, but its present encyclopedic form is the product of long growth. Flood myth, genealogy, temple architecture, iconography, royal duties and pilgrimage do not all belong to one compositional moment.`,`Its self-conscious discussion of the traditional five characteristics of a Purana is historically important, yet the work itself demonstrates the inadequacy of those five as a full contents list: large technical blocks on temples and images far exceed the pancalakshana scheme.`],
      contents:[S('Matsya and Manu — flood and preservation','The fish warns Manu and carries sages, seeds and sacred knowledge across cosmic destruction. Preservation of knowledge is therefore as important as biological survival.'),S('Cosmology, manvantaras and genealogy','Creation cycles and dynastic lists link the renewed world to sacred history and provide the old Puranic backbone of the text.'),S('Temple architecture and iconography','Detailed prescriptions for plans, measurements, divine images and consecration make Matsya a major source for the Sanskrit textualization of temple culture.'),S('Royal, ritual and pilgrimage compendia','Dharma, gifts, vows, kingship and sacred geography broaden the Purana into a practical religious encyclopedia.')],
      theology:[`Vishnu’s fish avatara does more than rescue Manu: it symbolizes the conservation and reorganization of knowledge that the encyclopedic Purana itself performs.`,`The text’s architectural and iconographic chapters make theology material: cosmic order is translated into measured sacred space and identifiable divine bodies.`],
      reception:[`Art historians frequently cite Matsya for architecture and iconography, but prescriptions cannot be used to date a monument mechanically. Textual instructions and workshop practice have separate, intersecting histories.`],
      sources:[W('Matsya Purāṇa')]
    },
    'Garuḍa Purāṇa':{
      period:'Medieval Vaishnava encyclopedia, substantially formed around the 9th–11th centuries with later growth; its funerary Pretakhanda has an especially complex transmission.',
      structure:'Two principal parts: Purvakhanda about 229 chapters (240–243 in some versions) and Uttarakhanda/Pretakhanda about 34–49 chapters; some editions add a Brahmakhanda.',
      rec:['Purvakhanda: encyclopedic Vaishnava material, chapter count varies.','Uttarakhanda/Pretakhanda: death and funerary material in several significantly different versions.','Venkateshvara editions may include an additional Brahmakhanda.'],
      date:[`The Garuda Purana’s popular identity as a “Hindu book of the dead” represents only one part of a much larger medieval encyclopedia. The Purvakhanda covers worship, medicine, gemology, polity, omens, yoga and other subjects; the Pretakhanda is the smaller but culturally famous funerary block.`,`The Pretakhanda itself is not textually uniform. Several substantially different versions circulate, and modern readers often encounter the still later Garuda Purana Saroddhara of Navanidhirama as though it were simply the Sanskrit Purana. Those texts must be distinguished.`],
      contents:[S('Purvakhanda — Vishnu and encyclopedic knowledge','The Vishnu-Garuda frame authorizes devotional, ritual and technical knowledge ranging from iconography and medicine to gems, omens and yoga.'),S('Pretakhanda — death and the preta state','The later part narrates post-mortem transition, Yama’s realm, consequences of action and the continuing relation between the dead and surviving family.'),S('Funerary rites','Offerings and timed rites are presented as assistance to a changing post-mortem person. The prescriptions belong to one scriptural strand within a much larger field of dharmashastra, priestly manuals and local custom.')],
      theology:[`The afterlife material is grounded in a Vaishnava moral cosmos: karma, judgment and ritual transition are ultimately framed by dependence on divine order rather than by punishment as an isolated fascination.`,`The work’s encyclopedic first half prevents the entire Purana from being reduced to fear of hell or funeral custom.`],
      reception:[`Modern vernacular publications often extract or paraphrase the Pretakhanda and sometimes conflate it with Navanidhirama’s Garuda Purana Saroddhara. Precise citation should distinguish the Sanskrit Purana, the recension of the Pretakhanda and later epitomes.`],
      sources:[W('Garuḍa Purāṇa')]
    },
    'Brahmāṇḍa Purāṇa':{
      period:'An old Puranic corpus with a core probably formed in the early-to-mid first millennium CE and major later accretions; closely related to the Vayu Purana.',
      structure:'Common printed form: 3 bhagas, the first subdivided into 2 padas, totaling about 156 chapters; recensions and Southeast Asian versions differ markedly.',
      rec:['Printed Sanskrit: Prakriya/Anushanga-type opening followed by Madhyama and Uttara bhagas, about 156 chapters.','Old Javanese Brahmanda materials preserve a shorter and sometimes more archaic-looking form.','Large embedded works such as the Lalitopakhyana have distinct transmission histories.'],
      date:[`The Brahmanda and Vayu Puranas share so much cosmological and genealogical material that they are best studied together. Their common ancestry belongs to an old Puranic stratum, while the surviving Brahmanda continued to absorb major theological and regional compositions.`,`Southeast Asian manuscript traditions are especially important because they prove that Brahmanda material travelled early and did not always possess the same huge late Sanskrit contents. The history of the text is therefore transregional as well as recensional.`],
      contents:[S('Cosmology, geography and dynastic history','The old core maps the cosmic egg, worlds, time cycles, sages and royal genealogies in close relation to Vayu-type material.'),S('Lalitopakhyana and Lalita theology','A major embedded Shakta cycle celebrates Lalita/Tripurasundari and includes the Lalita Sahasranama tradition, giving a powerful later Goddess layer to an older cosmological Purana.'),S('Adhyatma Ramayana tradition','The Adhyatma Ramayana is transmitted in association with the Brahmanda in many later traditions, recasting Rama through explicit Vedantic devotion; its textual history should be distinguished from the oldest Brahmanda core.'),S('Regional and Southeast Asian transmission','Javanese Brahmanda material shows how Puranic cosmology was transmitted and transformed outside the subcontinent.')],
      theology:[`The Brahmanda’s layers resist a single sectarian label. An old cosmological-genealogical framework came to house major Shakta and Rama-Vedantic compositions, turning the text into a record of successive theological appropriation.`,`The Lalita material is especially important for Sri Vidya traditions, but its prominence in later reception should not be projected backward onto every stratum of the Purana.`],
      reception:[`The Purana’s afterlife includes Sri Vidya recitation, Adhyatma Ramayana traditions and Old Javanese transmission. These are different reception histories attached to different textual blocks within the same expanding title.`],
      sources:[W('Brahmāṇḍa Purāṇa')]
    }
  };

  const classify=t=>{t=String(t||'').toLowerCase();if(/date|chronolog|formation|provenance|composition/.test(t))return'date';if(/structure|recension|transmission/.test(t))return'structure';if(/critical|edition|manuscript/.test(t))return'critical';if(/theolog|philosoph|interpret/.test(t))return'theology';if(/reception|influence|legacy/.test(t))return'reception';if(/rite|ritual|dharma|practice|pilgrim/.test(t))return'social';return'contents';};
  const routeNames=new Set(Object.keys(P));
  Object.entries(P).forEach(([name,p])=>{
    let e=D[`Purāṇa:${name}`]||D[name]||{};
    scrub(e);
    e.period=p.period;e.date='';e.dating='';e.history='';e.datingBasis='';e.hazraNotes='';e.milieu='';e.textualSetting='';
    e.structure=p.structure;e.extent=p.structure;e.booksCount=p.structure;e.primaryRecensions=p.rec||[];
    const sections=[
      C('Date and formation',p.date),
      C('Structure and transmission',p.rec?.length?[p.structure,`The structural details above refer to the surviving textual witnesses; traditional verse totals and lost forms are reported separately where relevant.`]:[p.structure]),
      C('Contents and distinctive profile',[],p.contents||[]),
      C('Theology and interpretation',p.theology||[]),
      C('Reception and influence',p.reception||[])
    ];
    if(p.critical?.length)sections.push(C('Critical edition and textual criticism',p.critical));
    e.articleSections=sections;
    e.sources=[...(e.sources||[]),ROCHER,HAZRA,...(p.sources||[])];
    e.scholarlyDepth='index-specific-v6';e.mahapuranaAudited=true;
    D[`Purāṇa:${name}`]=e;D[name]=Object.assign({},D[name]||{},e);
  });
})();
